internal static class Rc9Checks
{
    public static IEnumerable<(string Name,Action Run)> All(){
        yield return("rc9 targets exclude copy folders independently of their names",Targets);
        yield return("rc9 target context mutated to a junction is refused for both providers",JunctionMutation);
        yield return("rc9 EXE ranking excludes copies and tools with explicit Show All escape",Executables);
        yield return("rc9 future settings retain known keys but cannot inherit write authority",Settings);
        yield return("rc9 Restore conflicts preflight the whole transaction and preserve out-of-scope copies",RestoreScope);
        yield return("rc9 real WPF diagnostics recovery and long translations remain readable",Views);
        yield return("rc9 SDK Markdown admonitions render without executing content",Markdown);
        yield return("rc9 individual setting Details survive reload without writing configuration",SettingExpansion);
    }
    private static void Check(bool value,string message){if(!value)throw new Exception(message);}
    private static string Temp(){var path=Path.Combine(AppContext.BaseDirectory,"Rc9Checks",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(path);return path;}
    private static void Refuses(Action action){try{action();}catch(Exception ex)when(ex is InvalidDataException or IOException or InvalidOperationException){return;}throw new Exception("Expected safety refusal");}
    private static void Targets(){
        var root=Temp();var target=Path.Combine(root,"bin","x64_dx12");Directory.CreateDirectory(target);var exe=Path.Combine(target,"Own.exe");File.WriteAllText(exe,"fixture");
        RuntimeTargetPolicy.Validate(root,exe,target,false);RuntimeTargetPolicy.Validate(root,exe,target,true);
        foreach(var relative in new[]{"bin/x64_dx12_backup","bin/x64_dx12 - copy","bin/x64_dx12нгг – копія","unrelated/nested"}){var path=Path.Combine(root,relative);Directory.CreateDirectory(path);File.WriteAllText(Path.Combine(path,"libxess_fg.dll"),"do not change");foreach(var intel in new[]{true,false})Refuses(()=>RuntimeTargetPolicy.Validate(root,exe,path,intel));Check(File.ReadAllText(Path.Combine(path,"libxess_fg.dll"))=="do not change","Target check changed a copy");}
        var storage=Path.Combine(target,"_storage_");Directory.CreateDirectory(storage);Refuses(()=>RuntimeTargetPolicy.Validate(root,exe,storage,true));foreach(var a in IntelRuntimeService.Assets.Take(2))File.WriteAllText(Path.Combine(storage,a.Name),"existing pair fixture");RuntimeTargetPolicy.Validate(root,exe,storage,true);Refuses(()=>RuntimeTargetPolicy.Validate(root,exe,storage,false));Refuses(()=>RuntimeTargetPolicy.Validate(root,exe,Temp(),true));
    }
    private static void Executables(){var root=Temp();var paths=new[]{"bin/x64/witcher3.exe","bin/x64_dx12/witcher3.exe","bin/x64_dx12/d3dconfig.exe","bin/x64_dx12/crashreporter.exe","bin/x64_dx12 - copy/witcher3.exe","bin/x64_dx12нгг – копія/witcher3.exe","bin/x64_dx12_backup/witcher3.exe","custom.exe"};foreach(var relative in paths){var path=Path.Combine(root,relative);Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.WriteAllText(path,"never launched");}var normal=ExecutableCandidatePolicy.Discover(root);Check(normal.Count==3,"Tools/copies entered normal candidates");Check(ExecutableCandidatePolicy.Discover(root,true).Count==paths.Length,"Show All lost manual candidates");Check(ExecutableCandidatePolicy.KnownScore(normal.Single(p=>p.Contains("x64_dx12")),"292030")>ExecutableCandidatePolicy.KnownScore(normal.Single(p=>p.Contains("x64\\")),"292030"),"Known D3D12 candidate not ranked distinctly");Check(normal.Contains(Path.Combine(root,"custom.exe")),"Custom game EXE hidden");}
    private static void JunctionMutation()
    {
        var root=Temp();var target=Path.Combine(root,"exe-context");Directory.CreateDirectory(target);var exe=Path.Combine(target,"own.exe");File.WriteAllText(exe,"fixture");RuntimeTargetPolicy.Validate(root,exe,target,true);
        var relocated=Path.Combine(root,"original-context");Check(StreamlineStagingEvidenceService.IsStrictChild(root,target)&&StreamlineStagingEvidenceService.IsStrictChild(root,relocated),"Unsafe fixture move");Directory.Move(target,relocated);
        var outside=Temp();File.WriteAllText(Path.Combine(outside,"own.exe"),"outside fixture");
        using var process=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("cmd.exe",$"/c mklink /J \"{target}\" \"{outside}\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true})!;process.WaitForExit();if(process.ExitCode!=0)throw new SkipCheckException("Junction creation unavailable: "+process.StandardError.ReadToEnd());
        foreach(var intel in new[]{true,false}){try{RuntimeTargetPolicy.Validate(root,exe,target,intel);throw new Exception("Changed junction target allowed");}catch(InvalidDataException ex){Check(ex.Message.Contains("Reparse point"),"Mutation rejected only by unrelated policy");}}
        Check(File.ReadAllText(Path.Combine(outside,"own.exe"))=="outside fixture","Outside target changed");
    }
    private static void Settings(){var root=Temp();var main=new MfgUnlockSettingsService();var xe=new MfgUnlockSettingsService(true);var input="; retained\n[Other]\nK=abc\n[RenoDX.MFGUnlock]\nEnabled=1\nFutureKey=42\n";var path=Path.Combine(root,"ReShade.ini");File.WriteAllText(path,input);var snapshot=main.Load(path,root,"1.9.0.0");Check(snapshot.Settings.Any(s=>s.Definition.Key=="Rtx50QualityFixes")&&snapshot.IsSupportedAddonVersion,"Newer stable version lost inherited settings");var updated=System.Text.Encoding.UTF8.GetString(main.CreateUpdatedBytes(snapshot,new Dictionary<string,string>{{"Enabled","0"}}));Check(updated.Contains("FutureKey=42")&&File.ReadAllText(path)==input,"Preview changed source or unknown keys");var unknown=main.Load(path,root,"Unknown");Refuses(()=>main.CreateUpdatedBytes(unknown,new Dictionary<string,string>{{"Enabled","0"}}));Check(!xe.SupportsVersion("1.6.0.0")&&xe.SupportsVersion("1.7.0.0")&&xe.SupportsVersion("1.9.0.0"),"XeFG minimum gate incorrect");}
    private static void RestoreScope(){var root=Temp();var game=Path.Combine(root,"game");Directory.CreateDirectory(game);var a=Path.Combine(game,"a.dll");var b=Path.Combine(game,"b.dll");var other=Path.Combine(game,"copy","a.dll");Directory.CreateDirectory(Path.GetDirectoryName(other)!);File.WriteAllText(a,"original A");File.WriteAllText(other,"unrelated copy");var service=new BackupRestoreService(Path.Combine(root,"transactions"));var tx=service.ExecuteAsync(game,[new("a.dll",[1,2,3]),new("b.dll",[4,5])]).GetAwaiter().GetResult();File.WriteAllText(b,"Steam/external change");Check(!service.PreviewRestore(game,tx.TransactionId).CanRestore,"Conflict allowed Restore");Refuses(()=>service.RestoreAsync(game,tx.TransactionId).GetAwaiter().GetResult());Check(File.ReadAllBytes(a).SequenceEqual(new byte[]{1,2,3})&&File.ReadAllText(b)=="Steam/external change"&&File.ReadAllText(other)=="unrelated copy","Refusal modified a target");File.WriteAllBytes(b,[4,5]);service.RestoreAsync(game,tx.TransactionId).GetAwaiter().GetResult();Check(File.ReadAllText(a)=="original A"&&!File.Exists(b)&&File.ReadAllText(other)=="unrelated copy","Restore exceeded manifest scope");}
    private static IEnumerable<DependencyObject> Tree(DependencyObject root){for(var i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);yield return child;foreach(var nested in Tree(child))yield return nested;}}
    private static MainWindow Shell(){var main=new MainWindow();main.Loaded-=typeof(MainWindow).GetMethod("Window_Loaded",BindingFlags.Instance|BindingFlags.NonPublic)!.CreateDelegate<RoutedEventHandler>(main);main.Show();return main;}
    private static void Drain(Window w){w.UpdateLayout();Dispatcher.CurrentDispatcher.Invoke(()=>{},DispatcherPriority.ApplicationIdle);w.UpdateLayout();}
    private static void Views()=>WpfCheckHost.Run(()=>{var main=Shell();var panel=new RuntimeDiagnosticsPanel();var report=new RuntimeDiagnosticReport(["Runtime loaded: NOT VERIFIED."],["Disk · own.dll · Unknown version","Previous session evidence only"],["Own warning"],[new("Own-ReShade.log","> [!NOTE]\nraw original log",DateTimeOffset.UtcNow)]);panel.Render(report);var dialog=main.CreateInfoDialog("Runtime Diagnostics",panel);var trace=new StringWriter();var listener=new System.Diagnostics.TextWriterTraceListener(trace);System.Diagnostics.PresentationTraceSources.DataBindingSource.Listeners.Add(listener);try{dialog.Show();foreach(var culture in UiLocalization.Cultures){LocalizedPresentation.Language.SetCulture(culture,false);foreach(var name in new[]{"Overview","Installed Components","Session / Loaded Modules","Logs","Warnings"}){Tree(panel).OfType<Button>().Single(b=>LocalizedPresentation.SourceText(b,ContentControl.ContentProperty)==name).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Drain(dialog);Check(Tree(panel).OfType<Button>().Any(b=>b.Content as string==LocalizedPresentation.Language.Lookup(name)),"Diagnostics tab not localized");if(name=="Logs")Check(Tree(panel).OfType<TextBox>().Single(t=>t.IsReadOnly).Text==report.Logs![0].Text,"Raw log translated or lost");}Check(main.FindName("ExpertDiagnosticsExpander") is null,"Duplicate expert inspector still in primary UI");Check(!Tree((DependencyObject)main.FindName("MfgSettingsPage")).OfType<Button>().Any(b=>LocalizedPresentation.SourceText(b,ContentControl.ContentProperty)=="Guide / Help"),"Global help remains");}dialog.Close();var preview=new BackupRestorePreview("own-transaction","Conflict",true,false,"Own conflict",[new("nested/a.dll","Restore original","Changed externally","Not written")]);var view=main.RestorePreviewContent(preview,Temp(),main);var recovery=main.CreateInfoDialog("Restore",view);recovery.Show();Drain(recovery);Check(Tree(view).OfType<TextBlock>().Any(t=>t.Text.Contains("nested/a.dll")),"Recovery file table missing paths");recovery.Close();foreach(var size in new[]{(1040d,650d),(1440d,900d)}){main.Width=size.Item1;main.Height=size.Item2;Drain(main);Check(((FrameworkElement)main.FindName("HomePage")).ActualWidth<=main.ActualWidth,"Main page overflow");}listener.Flush();Check(!trace.ToString().Contains("Error:"),"Binding error: "+trace);}finally{System.Diagnostics.PresentationTraceSources.DataBindingSource.Listeners.Remove(listener);dialog.Close();main.Close();}});
    private static void Markdown()=>WpfCheckHost.Run(()=>{var main=Shell();try{var document=(FlowDocument)typeof(MainWindow).GetMethod("BuildReleaseNotesDocument",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(main,["> [!IMPORTANT]\n> Keep notices\n# Heading\n- item\n[unsafe](javascript:alert)\n<script>never executed</script>"])!;var text=new TextRange(document.ContentStart,document.ContentEnd).Text;Check(text.Contains("IMPORTANT")&&!text.Contains("[!IMPORTANT]")&&text.Contains("Keep notices"),"Admonition left raw");Check(!document.Blocks.OfType<Paragraph>().SelectMany(p=>p.Inlines.OfType<Hyperlink>()).Any(),"Unsafe hyperlink accepted");}finally{main.Close();}});
    private static void SettingExpansion()=>WpfCheckHost.Run(()=>{
        var main=Shell();const BindingFlags flags=BindingFlags.NonPublic|BindingFlags.Instance;var type=typeof(MainWindow);try{
            var root=Temp();var exe=Path.Combine(root,"own-settings-ui.exe");File.WriteAllText(exe,"never launched");type.GetField("selectedExe",flags)!.SetValue(main,exe);type.GetField("selectedGameRoot",flags)!.SetValue(main,root);
            type.GetMethod("SetPage",flags)!.Invoke(main,[Enum.Parse(type.GetNestedType("AppPage",BindingFlags.NonPublic)!,"MfgSettings")]);
            void Load(){var task=(Task)type.GetMethod("LoadMfgSettingsAsync",flags)!.Invoke(main,[])!;var until=DateTime.UtcNow.AddSeconds(5);while(!task.IsCompleted&&DateTime.UtcNow<until)Drain(main);Check(task.IsCompleted,"Settings read timed out");task.GetAwaiter().GetResult();Drain(main);}
            Expander First()=>Tree((FrameworkElement)main.FindName("MfgSettingsItemsControl")).OfType<Expander>().First();
            Load();First().IsExpanded=true;Drain(main);Load();Check(First().IsExpanded,"Reload collapsed individual help");First().IsExpanded=false;Drain(main);Load();Check(!First().IsExpanded,"Reload reopened collapsed help");Check(!File.Exists(Path.Combine(root,"ReShade.ini"))&&!File.Exists(Path.Combine(root,"MFGAdaUnlock.ini")),"Readonly UI load wrote configuration");
        }finally{main.Close();}
    });
}
